//! Versioned request and response wrappers for the unified TrUAPI contract.
//!
//! A versioned envelope is a SCALE enum whose variants (`V1`, `V2`, ...) are
//! successive versions of one logical message, newest last. A server normalizes
//! incoming values to [`Versioned::Latest`] with [`IntoLatest`], handles them in
//! latest terms, then maps results back to the caller's version with
//! [`FromLatest`]. The envelopes themselves are generated by `versioned_type!`,
//! and each variant wraps either `Request` or `Subscription` rather than a bare
//! payload: version selects a method's shape, direction is carried inside that
//! version's payload rather than addressed by a separate wire id.

use parity_scale_codec::{Decode, Encode};

/// A versioned message envelope.
pub trait Versioned: Sized {
    /// The newest version's payload. Handlers operate exclusively on this.
    type Latest;

    /// Version number of the newest variant.
    const LATEST: u8;

    /// Version number of the variant currently held.
    fn version(&self) -> u8;
}

/// Upgrade a received envelope to its latest payload. Total by construction.
pub trait IntoLatest: Versioned {
    /// Convert whatever version is held into the latest payload.
    fn into_latest(self) -> Self::Latest;
}

/// Downgrade a latest payload into the variant a peer at `target` understands.
pub trait FromLatest: Versioned {
    /// Build the envelope for protocol version `target` (highest variant ≤ target).
    fn from_latest(latest: Self::Latest, target: u8) -> Self;
}

/// Direction tag for a request/response method: which half of the exchange
/// this frame carries. Wrapped inside a method's version enum, so a method's
/// version history is the one place its shape can change.
// Not yet referenced outside this module's own tests: the generated code that
// wraps every method's version enum in this lands in a separate stacked PR.
#[allow(dead_code)]
#[derive(Debug, Clone, PartialEq, Eq, Encode, Decode)]
pub(crate) enum Request<Req, Res> {
    /// Product-to-host call.
    Request(Req),
    /// Host-to-product reply.
    Response(Res),
}

/// Direction tag for a subscription method: which half of the four-frame
/// exchange this frame carries. `Start` and `Receive` lead, in the same
/// position as [`Request`]'s own two variants, so subscription decoding is
/// partly shape-compatible with request decoding. `Stop` carries no payload;
/// `Interrupt` carries `None` for natural stream completion or `Some(err)`
/// for a failure.
#[allow(dead_code)]
#[derive(Debug, Clone, PartialEq, Eq, Encode, Decode)]
pub(crate) enum Subscription<Start, Item, Err> {
    /// Product-to-host subscription request.
    Start(Start),
    /// Host-to-product streamed item.
    Receive(Item),
    /// Host-to-product termination: `None` on clean completion, `Some` on failure.
    Interrupt(Option<Err>),
    /// Product-to-host cancellation.
    Stop,
}

